import{_ as t,o as i,c as e,a5 as a}from"./chunks/framework.CsGesDJn.js";const s=JSON.parse('{"title":"Kế hoạch kỹ thuật","description":"","frontmatter":{},"headers":[],"relativePath":"feature/caption-trend-retrieval/plan.md","filePath":"feature/caption-trend-retrieval/plan.md"}'),o={name:"feature/caption-trend-retrieval/plan.md"};function h(c,n,r,l,d,u){return i(),e("div",null,[...n[0]||(n[0]=[a('<h1 id="ke-hoach-ky-thuat" tabindex="-1">Kế hoạch kỹ thuật <a class="header-anchor" href="#ke-hoach-ky-thuat" aria-label="Permalink to &quot;Kế hoạch kỹ thuật&quot;">​</a></h1><h2 id="luong-muc-tieu" tabindex="-1">Luồng mục tiêu <a class="header-anchor" href="#luong-muc-tieu" aria-label="Permalink to &quot;Luồng mục tiêu&quot;">​</a></h2><p>Business xác thực workspace và lấy brand/task → AI resolve trendId → Neo4j trả graph context và danh sách run/post được phép → embedding query → Chroma truy xuất evidence thuộc trend/run đó → hợp nhất với brand KB đã lọc tenant → tạo một context snapshot → LLM tạo ba variant → kiểm tra chất lượng/moderation → lưu kết quả và provenance.</p><p>Neo4j cung cấp thực thể/quan hệ, Chroma cung cấp ngữ cảnh văn bản. Redis có thể tiếp tục cache hoặc cung cấp trạng thái publication theo cơ chế hiện có; không dùng Redis thay cho nguồn evidence graph/vector trong tính năng này. Không dựng thêm một hệ thống GraphRAG tổng quát hay nâng major database ở P0.</p><h2 id="giai-đoan-1-audit-va-chuan-hoa-du-lieu" tabindex="-1">Giai đoạn 1: audit và chuẩn hóa dữ liệu <a class="header-anchor" href="#giai-đoan-1-audit-va-chuan-hoa-du-lieu" aria-label="Permalink to &quot;Giai đoạn 1: audit và chuẩn hóa dữ liệu&quot;">​</a></h2><ol><li>Audit read-only schema, collection metadata, index, embedding model/dimension, phân bố runId/trendId/postId và tỷ lệ thiếu sourceUrl/time. Kiểm tra join thực giữa Neo4j và Chroma, không chỉ so tên field.</li><li>Chuẩn hóa post identity (platform + postId) vì graph dùng ID có platform prefix còn Chroma lưu postId và platform riêng. Trend ID có ngày/category nên không join chỉ bằng keyword. Không yêu cầu mọi post có Entity.</li><li>Hiện chunk ID v2 gộp theo trend/platform/post và có thể bị upsert qua nhiều run. Đánh giá nhu cầu schema v3 thêm runId vào identity hoặc dùng revision mapping để không overwrite evidence đang được generation tham chiếu. Giữ v2, backfill có dry-run/idempotence; không xóa collection hiện hữu.</li><li>Thiết kế publication allowlist. Nếu graph chưa có run publication marker, đọc trạng thái publish hiện có ở Redis một cách tường minh. Bền vững hơn: lưu publication manifest/revision trong Neo4j sau khi graph/vector writes được xác nhận. Không giả định có transaction chung hai DB. Nội dung chưa publish vẫn là staging, không đủ điều kiện retrieve.</li><li>Thiếu metadata/version không được đoán từ ngày trend để coi là nguồn hiện hành. Backfill được provenance thì đưa vào; không chứng minh được thì loại khỏi retrieval mới và báo coverage thiếu.</li></ol><h2 id="giai-đoan-2-retrieval-trong-ai" tabindex="-1">Giai đoạn 2: retrieval trong AI <a class="header-anchor" href="#giai-đoan-2-retrieval-trong-ai" aria-label="Permalink to &quot;Giai đoạn 2: retrieval trong AI&quot;">​</a></h2><p>Thêm <code>caption_trend_context.py</code> điều phối và model context/provenance riêng. Tái sử dụng Neo4j driver, VectorStoreService/EmbeddingService và trend-fit safety thay vì mở client/model mới mỗi request.</p><ul><li>Neo4j query tham số hóa, graph depth tối đa 1 ở P0, giới hạn số entity/post; không gọi Graph UI expansion API cho mỗi caption.</li><li>Query <code>social_trend_chunks</code> với filter trendId + allowlisted runId/namespace và post identity khi có. Query brand KB tách biệt, luôn <code>clientId</code> lấy từ Business.</li><li>Dùng cùng embedding model, dimension, normalization và query/passage prefix của indexing. Không đổi embedding model trực tiếp trên collection đã có. Retrieval chỉ đọc collection, không dùng <code>get_or_create</code> để tự tạo collection sai cấu hình trong request.</li><li>Lọc ngày publish/crawl theo policy minh bạch, ưu tiên ngữ nghĩa và tính đa dạng nguồn; cosine distance không gọi là confidence tuyệt đối. Calibrate threshold bằng dữ liệu đánh giá.</li><li>Khởi điểm để đo: lấy tối đa 20 candidate chunks, chọn 4–6 chunks, tối đa 2 chunk/post; context trend khoảng 2.000 tokens. Graph/vector timeout mục tiêu 2–3 giây mỗi nguồn, tổng retrieval budget khoảng 5 giây; là tham số đề xuất, chưa phải SLA đã đo.</li><li>Cache ngắn hạn theo workspace/brand revision + topic + platform + trendId + publication revision + policy version. Giới hạn kích thước cache, không giữ toàn bộ collection trong RAM. Tái dùng singleton embedding; hạn chế concurrent embedding query để không tái tạo OOM khi crawler chạy cùng.</li></ul><h2 id="giai-đoan-3-tich-hop-caption-business-va-ui" tabindex="-1">Giai đoạn 3: tích hợp caption, Business và UI <a class="header-anchor" href="#giai-đoan-3-tich-hop-caption-business-va-ui" aria-label="Permalink to &quot;Giai đoạn 3: tích hợp caption, Business và UI&quot;">​</a></h2><ol><li><code>content.py</code>: resolve event trend từ ngữ cảnh mới; moment/format đi nhánh hiện hữu; phân biệt invalid ID với DB unavailable. Không bọc lỗi retrieval thành caption giả.</li><li><code>caption_service.py</code>: thêm evidence block tách biệt brand facts/social reports; bỏ việc gắn nhãn toàn bộ bài crawl là verified. Không dùng một con số từ bài xã hội làm bằng chứng cho giá/ưu đãi của brand.</li><li>Giữ một LLM call tạo ba variant; giữ kiểm tra schema, độ dài, số/claim, trend fit và moderation. Xem lại heuristic <code>trend_used</code> hiện chỉ khớp keyword để không coi đó là chứng minh grounding.</li><li><code>AiCaptionService.java</code> và DTO/context persistence: bổ sung metadata optional, tenant context từ server; idempotent request reuse snapshot, không thu thêm credit chỉ do retry retrieval.</li><li>Web mở rộng picker/context preview trong luồng hiện có, vi/en và theme song song; nguồn tham khảo có link/thời gian, không nhét technical metadata vào caption. Refine/adapt dùng generation context được xác thực thay vì tin context tùy ý từ client.</li></ol><h2 id="giai-đoan-4-đanh-gia-va-rollout" tabindex="-1">Giai đoạn 4: đánh giá và rollout <a class="header-anchor" href="#giai-đoan-4-đanh-gia-va-rollout" aria-label="Permalink to &quot;Giai đoạn 4: đánh giá và rollout&quot;">​</a></h2><p>Feature flag mặc định tắt; dev → staging/QA → production sau duyệt. Đầu tiên selected-trend P0; P1 auto-suggest chỉ sau khi P0 có số liệu. Rollback tắt flag và về gen thường/chọn trend theo luồng cũ có thông báo phù hợp, không xóa graph/vector. Không thay cấu hình/code trực tiếp production.</p><p>Tài liệu tham chiếu kỹ thuật: <a href="https://github.com/chroma-core/docs/blob/main/docs/usage-guide.md" target="_blank" rel="noreferrer">Chroma query/filter</a>, <a href="https://neo4j.com/docs/cypher-manual/current/syntax/parameters/" target="_blank" rel="noreferrer">Cypher parameters</a>. Kiểm tra cú pháp bằng chính phiên bản Neo4j/Chroma đang dùng trước triển khai; không lấy tính năng mới ở bản cloud/latest để áp mặc định cho bản local.</p>',14)])])}const p=t(o,[["render",h]]);export{s as __pageData,p as default};
